xml.Script:
        Colors[0] := 'F0F0F0'; // White 
        Colors[1] := '0000FF'; // Blue  
        Colors[2] := 'FF0000'; // Red   
        Colors[3] := 'FFFF00'; // Yellow
        Colors[4] := 'FF6000'; // Orange
        Colors[5] := '008000'; // Green 
        Colors[6] := '00FFFF'; // Cyan  
        Colors[7] := '00FF00'; // Lime  
        Colors[8] := 'F0E68C'; // Khaki 
        Colors[9] := '505080'; // Gray  

        K := 0.42;
        s3  := sqrt(3);
        D := K / s3;
        RC := K * 0.378;

        aX := s3 / 2;
        aZ := 1 / 2;

        jAngle := Arccos(-3/5);

        pX0 := K;
        pZ0 := K * 2 / s3;

        pX1 := K * 3 / 2;
        pZ1 := K / 2 / s3;

        pX2 := K;
        pZ2 :=-K / s3;

        pX3 := pX2 + (pX2 - pX1);
        pZ3 := pZ2 + (pZ2 - pZ1);

        procedure Add4( x, y, z);
        begin
            Vx[i] := x; Vy[i] := y; Vz[i] := z; Inc(i);
            Vx[i] :=-y; Vy[i] := x; Vz[i] := z; Inc(i);
            Vx[i] :=-x; Vy[i] :=-y; Vz[i] := z; Inc(i);
            Vx[i] := y; Vy[i] :=-x; Vz[i] := z; Inc(i);
        end;

        i := 0;
        Add4( pX0,   0, pZ0);
        Add4( pX1,   0, pZ1);
        Add4( pX2, pX2, pZ2);
        Add4( pX3,   0, pZ3);

        pX5 := K * 5 / 7;
        pZ5 := pX5 / s3;
        pX6 := K;
        pZ6 :=-K / s3;

        Cx[0] :=   0; Cy[0] :=   0; Cz[0] := pZ0;
        Cx[1] := pX6; Cy[1] :=   0; Cz[1] := pZ6;
        Cx[2] :=   0; Cy[2] := pX6; Cz[2] := pZ6;
        Cx[3] :=-pX6; Cy[3] :=   0; Cz[3] := pZ6;
        Cx[4] :=   0; Cy[4] :=-pX6; Cz[4] := pZ6;
        Cx[5] :=   0; Cy[5] :=   0; Cz[5] := pZ3;

        // Circle centers
        CCx[0] := pX5; CCy[0] := pX5; CCz[0] := pZ5;
        CCx[1] :=-pX5; CCy[1] := pX5; CCz[1] := pZ5;
        CCx[2] :=-pX5; CCy[2] :=-pX5; CCz[2] := pZ5;
        CCx[3] := pX5; CCy[3] :=-pX5; CCz[3] := pZ5;

        pillow := 1.2;
        for i := 0 to 4 do begin
          Cx[i] := Cx[i] * pillow;
          Cy[i] := Cy[i] * pillow;
          Cz[i] := Cz[i] * pillow;
        end;
